+bool parseScheduleEntry(const std::string& s, ScheduleEntry& out) {
+    const auto c1 = s.find(',');
+    if (c1 == std::string::npos) return false;
+    const auto c2 = s.find(',', c1 + 1);
+    if (c2 == std::string::npos) return false;
