+        out.startHour = std::stof(hours.substr(0, dash));
+        out.endHour = std::stof(hours.substr(dash + 1));
+        out.position.x = std::stof(trim(s.substr(c1 + 1, c2 - c1 - 1)));
+        out.position.z = std::stof(trim(s.substr(c2 + 1, c3 - c2 - 1)));
