101	void Npc::faceToward(const Vec3& target) {
102	    const float dx = target.x - position_.x;
103	    const float dz = target.z - position_.z;
104	    if (dx * dx + dz * dz < 1e-6f) return;  // on top of target; keep facing
105	    // Yaw convention matches flatForward/forwardFromAngles: 0 looks toward +Z,
106	    // increasing toward +X, hence atan2(dx, dz).
107	    facingDeg_ = std::atan2(dx, dz) * 180.f / 3.14159265358979323846f;
108	}
